/// <summary>
/// PricingAttribute of table <c>CustTable</c> field LineDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, LineDisc))]
internal class GUPPricingAttributeCustTableLineDisc extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, LineDisc);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable       custTable;
    PriceDiscGroup  priceDiscGroup;

    while select LineDisc from custtable
        group by LineDisc
        join priceDiscGroup
        group by GroupId, Name, Module, Type
        where custTable.LineDisc == priceDiscGroup.GroupId && priceDiscGroup.Module  == ModuleInventCustVend::Cust &&
                  priceDiscGroup.Type == PriceGroupType::LineDiscGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
